import java.nio.file.*;
import java.util.*;
import spoon.Launcher;
import spoon.reflect.declaration.CtMethod;
import spoon.reflect.visitor.filter.TypeFilter;
import latte.api.*;
import latte.analysis.*;
import latte.refinement.LiquidTypeChecking;
import com.google.gson.GsonBuilder;
public class EffectAblation {
  public static void main(String[] args) throws Exception {
    var launcher = new Launcher();
    launcher.getEnvironment().setComplianceLevel(21);
    launcher.getEnvironment().setNoClasspath(true);
    launcher.getEnvironment().setCommentEnabled(false);
    launcher.addInputResource(args[0]);
    Jdk21Contracts.addTo(launcher,List.of("all"));
    var model = launcher.buildModel();
    if (args[1].equals("without-summaries"))
      for (var method : model.getElements(new TypeFilter<>(CtMethod.class)))
        for (var annotation : List.copyOf(method.getAnnotations()))
          if (Set.of("Modifies","ReturnsView").contains(annotation.getAnnotationType().getSimpleName()))
            method.removeAnnotation(annotation);
    var diagnostics = new ArrayList<Diagnostic>(new LatteAnalysis().analyze(model));
    diagnostics.addAll(new LiquidTypeChecking().analyze(model));
    Files.writeString(Path.of(args[2]),new GsonBuilder().setPrettyPrinting().create().toJson(diagnostics.stream().distinct().toList())+"\n");
  }
}

