import liquidjava.specification.*;
class RepeatedAllocationLimit {
  @StateSet({"open", "closed"}) static class Resource {
    @StateRefinement(to="open(this)") Resource() {}
    @StateRefinement(from="open(this)") void read() {}
  }
  void repeated() {
    Resource previous = null;
    for (int i = 0; i < 3; i++) {
      Resource current = new Resource();
      current.read();
      if (previous != null) previous.read(); // Expect: SHARED_REFINEMENT
      previous = current;
    }
  }
  void separateSites() {
    Resource first = new Resource(); first.read();
    Resource second = new Resource(); first.read(); second.read();
    Resource third = new Resource(); second.read(); third.read();
  }
}
